<script setup lang="ts">import {computed,ref} from 'vue';import StatCards from '../../components/common/StatCards.vue';import EntityTable from '../../components/common/EntityTable.vue';import ApprovalDetailPanel from '../../components/approval/ApprovalDetailPanel.vue';import ApprovalForm from '../../components/approval/ApprovalForm.vue';import DetailDrawer from '../../components/common/DetailDrawer.vue';type Approval={id:string;title:string;type:string;applicantName:string;customer:string;status:string;createdAt:string;attachments:Array<{name:string;url?:string;size?:string}>};const tab=ref('pending');const keyword=ref('');const selected=ref<Record<string,unknown>|null>(null);const createOpen=ref(false);const approvals=ref<Approval[]>([{id:'A-001',title:'合同用印审批',type:'合同',applicantName:'张三',customer:'国家电网',status:'待审批',createdAt:'2026-09-09',attachments:[]},{id:'A-002',title:'采购付款审批',type:'付款',applicantName:'李四',customer:'供应商A',status:'已通过',createdAt:'2026-09-08',attachments:[]}]);const rows=computed(()=>approvals.value.filter(item=>(tab.value==='pending'?item.status==='待审批':tab.value==='history'?item.status!=='待审批':true)&&Object.values(item).some(v=>String(v).toLowerCase().includes(keyword.value.toLowerCase()))));const action=(status:string)=>{if(selected.value){selected.value.status=status;const i=approvals.value.findIndex(x=>x.id===selected.value?.id);if(i>=0)approvals.value[i]={...approvals.value[i],...selected.value} as Approval;selected.value=null}};const create=(value:Record<string,string>)=>{approvals.value.unshift({id:`A-${String(approvals.value.length+1).padStart(3,'0')}`,title:value.title||'未命名审批',type:value.type||'其他',applicantName:value.applicantName||'—',customer:value.customer||'—',comment:value.comment,status:'待审批',createdAt:new Date().toISOString().slice(0,10),attachments:[]} as Approval);createOpen.value=false;tab.value='all'};</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">APPROVAL CENTER</span><h2>审批中心</h2></div><div><span class="tag">Vue 页面迁移</span><button class="primary" @click="createOpen=true">发起审批</button></div></div><StatCards :items="[{label:'待我审批',value:String(approvals.filter(x=>x.status==='待审批').length)},{label:'我发起的',value:String(approvals.length)},{label:'已通过',value:String(approvals.filter(x=>x.status==='已通过').length)},{label:'数据状态',value:'本地适配'}]"/><div class="tabs"><button :class="{active:tab==='pending'}" @click="tab='pending'">待我审批</button><button :class="{active:tab==='all'}" @click="tab='all'">全部申请</button><button :class="{active:tab==='history'}" @click="tab='history'">审批记录</button></div><div class="toolbar"><input v-model="keyword" placeholder="搜索审批标题、申请人或客户"/><span>{{rows.length}} 条记录</span></div><EntityTable :columns="['审批标题','类型','申请人','关联客户','状态','创建时间']" :rows="rows" :cell="(row,index)=>[row.title,row.type,row.applicantName,row.customer,row.status,row.createdAt][index]||'—'" @select="selected=$event"/><ApprovalDetailPanel v-if="selected" :approval="selected" @approve="action('已通过')" @reject="action('已驳回')"/><DetailDrawer :open="createOpen" title="发起审批" @close="createOpen=false"><ApprovalForm @save="create" @cancel="createOpen=false"/></DetailDrawer></section></template>
